#!/usr/bin/env bash
# fix-oss-checksums.sh — fix "NotImplemented: Aws MultiChunkedEncoding STREAMING-UNSIGNED-PAYLOAD-TRAILER"
# (boto3 >= 1.36 default flexible checksums are not supported by Aliyun OSS).
# Deploys the fixed storage.py, rebuilds backend+worker, restarts nginx, then re-processes
# any media rows stuck in failed/processing so they reach 'ready'.
set -euo pipefail

cd /opt/wedding-app/backend/src/services
cp storage.py storage.py.bak 2>/dev/null || true
base64 -d > storage.py <<'B64_STORAGE'

B64_STORAGE

echo "== Sanity check =="
grep -cF 'request_checksum_calculation="when_required"' storage.py

echo "== Rebuilding backend + worker (a few minutes) =="
cd /opt/wedding-app/infra
docker compose -f docker-compose.prod.yml build backend worker
docker compose -f docker-compose.prod.yml up -d backend worker
docker compose -f docker-compose.prod.yml restart nginx
sleep 15

echo "== Health =="
curl -sk https://localhost:8443/api/v1/health && echo

echo "== Re-processing failed/stuck media =="
docker compose -f docker-compose.prod.yml exec -T backend uv run python - <<'PYEOF'
import asyncio
from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession, create_async_engine

from src.config import get_settings
from src.models.media import Media
from src.workers.media_processing import process_media


async def main() -> None:
    engine = create_async_engine(get_settings().database_url)
    async with AsyncSession(engine) as s:
        rows = (await s.execute(
            select(Media).where(Media.status.in_(["failed", "processing"]))
        )).scalars().all()
        if not rows:
            print("no failed/processing rows — nothing to repair")
            return
        for m in rows:
            m.status = "processing"  # let process_media accept it
            await process_media(s, m)
            await s.commit()
            await s.refresh(m)
            print(f"  id={m.id} ({m.filename}) -> {m.status}")


asyncio.run(main())
PYEOF

echo ""
echo "DONE. If every id above shows 'ready', uploads are fully fixed."
echo "Remaining manual step: add the OSS bucket CORS rule in the console (browser uploads need it)."